1|// Domain: The Flow — boot reconcile PIN (S7): server-restart orphans stay at zero.
2|import { describe, test, expect, vi, beforeEach } from "vitest";
3|import { reconcileInterruptedRuns } from "./reconcileInterruptedRuns.js";
4|
5|const RESTART_HISTORY_ROW = "Stage execution interrupted by server restart";
6|
7|function makeBootStore({ projects, tasksByProject, activeTaskId = null } = {}) {
8|	const store = {
9|		projectStore: {
10|			listProjects: () => projects,
11|		},
12|		engineState: { status: "idle", activeTaskId },
13|		listTasks: (projectId) => tasksByProject.get(projectId) ?? [],
14|		_recordHistory: vi.fn((task, action, timestamp) => {
15|			task.history = task.history || [];
16|			task.history.push({ timestamp, action });
17|		}),
18|		_saveTaskMarkdown: vi.fn(),
19|	};
20|	return store;
21|}
22|
23|function bootTask(overrides = {}) {
24|	return {
25|		id: "t-1",
26|		projectId: "p-1",
27|		status: "in_stage",
28|		updatedAt: "2026-09-24T10:00:00.000Z",
29|		history: [],
30|		...overrides,
31|	};
32|}
33|
34|function seedBootStore(tasks, { activeTaskId = null } = {}) {
35|	const projects = [{ id: "p-1", name: "P", cwd: "/repo" }];
36|	const tasksByProject = new Map([[projects[0].id, tasks]]);
37|	return makeBootStore({ projects, tasksByProject, activeTaskId });
38|}
39|
40|beforeEach(() => {
41|	vi.clearAllMocks();
42|});
43|
44|describe("reconcileInterruptedRuns boot PIN (S7)", () => {
45|	test("orphaned running_* tasks flip to interrupted with a server-restart history row", () => {
46|		const orphanStatuses = ["running_agent", "running_ci", "running_merge", "advancing"];
47|		const orphans = orphanStatuses.map((status, index) =>
48|			bootTask({ id: `orphan-${index}`, status }),
49|		);
50|		const control = bootTask({ id: "control", status: "in_stage" });
51|		const tasks = [...orphans, control];
52|		const before = new Map(tasks.map((task) => [task.id, task.updatedAt]));
53|		const store = seedBootStore(tasks);
54|
55|		const reconciled = reconcileInterruptedRuns(store);
56|
57|		for (const orphan of orphans) {
58|			expect(orphan.status).toBe("interrupted");
59|			expect(orphan.wasInterrupted).toBe(true);
60|			expect(orphan.updatedAt).not.toBe(before.get(orphan.id));
61|			expect(store._recordHistory).toHaveBeenCalledWith(
62|				orphan,
63|				RESTART_HISTORY_ROW,
64|				orphan.updatedAt,
65|			);
66|			expect(orphan.history.at(-1)).toMatchObject({ action: RESTART_HISTORY_ROW });
67|		}
68|		expect(reconciled).toEqual(
69|			orphans.map((orphan) => ({ projectId: "p-1", taskId: orphan.id })),
70|		);
71|		expect(control.status).toBe("in_stage");
72|		expect(control.wasInterrupted).toBeUndefined();
73|		expect(control.updatedAt).toBe(before.get(control.id));
74|		expect(control.history).toEqual([]);
75|		expect(reconciled).not.toContainEqual({ projectId: "p-1", taskId: control.id });
76|	});
77|
78|	test("the engine owner's live task is untouched", () => {
79|		const owner = bootTask({ id: "owner", status: "running_agent" });
80|		const orphan = bootTask({ id: "orphan", status: "running_ci" });
81|		const store = seedBootStore([owner, orphan], { activeTaskId: owner.id });
82|
83|		const reconciled = reconcileInterruptedRuns(store);
84|
85|		expect(owner.status).toBe("running_agent");
86|		expect(owner.wasInterrupted).toBeUndefined();
87|		expect(owner.history).toEqual([]);
88|		expect(store._recordHistory).not.toHaveBeenCalledWith(
89|			owner,
90|			expect.anything(),
91|			expect.anything(),
92|		);
93|		expect(reconciled).not.toContainEqual({ projectId: "p-1", taskId: owner.id });
94|		expect(orphan.status).toBe("interrupted");
95|		expect(reconciled).toEqual([{ projectId: "p-1", taskId: orphan.id }]);
96|	});
97|
98|	test("a second pass reconciles nothing and writes no further history (idempotent)", () => {
99|		const orphan = bootTask({ id: "orphan", status: "running_merge" });
100|		const store = seedBootStore([orphan]);
101|
102|		const first = reconcileInterruptedRuns(store);
103|		expect(first).toEqual([{ projectId: "p-1", taskId: orphan.id }]);
104|		const historyCallsAfterFirst = store._recordHistory.mock.calls.length;
105|		expect(historyCallsAfterFirst).toBeGreaterThan(0);
106|
107|		const second = reconcileInterruptedRuns(store);
108|
109|		expect(second).toEqual([]);
110|		expect(store._recordHistory.mock.calls.length).toBe(historyCallsAfterFirst);
111|		expect(orphan.status).toBe("interrupted");
112|	});
113|
114|	test("legacy running_deploy records still reconcile", () => {
115|		const legacy = bootTask({ id: "legacy", status: "running_deploy" });
116|		const store = seedBootStore([legacy]);
117|
118|		const reconciled = reconcileInterruptedRuns(store);
119|
120|		expect(legacy.status).toBe("interrupted");
121|		expect(legacy.wasInterrupted).toBe(true);
122|		expect(store._recordHistory).toHaveBeenCalledWith(
123|			legacy,
124|			RESTART_HISTORY_ROW,
125|			legacy.updatedAt,
126|		);
127|		expect(reconciled).toEqual([{ projectId: "p-1", taskId: legacy.id }]);
128|	});
129|});

