1|// Domain: The Flow — boot reconcile PIN (S7): server-restart orphans stay at zero.
2|// Regression pin per GUIDE-06 §2: the one path that SHOULD write
3|// "Stage execution interrupted by server restart" is reconcileInterruptedRuns,
4|// run at boot by performStartupRecovery. Any "interrupted by server restart"
5|// row in prod re-opens Cause 6; any other writer of that string is a bug.
6|import { describe, test, expect, vi, beforeEach } from "vitest";
7|import { reconcileInterruptedRuns } from "./reconcileInterruptedRuns.js";
8|import { ORPHANED_RUNNING_STATUSES } from "./orphanedRunningStatuses.js";
9|
10|const RESTART_HISTORY_ROW = "Stage execution interrupted by server restart";
11|
12|function makeBootStore({ projects, tasksByProject, activeTaskId = null } = {}) {
13|	const store = {
14|		projectStore: {
15|			listProjects: () => projects,
16|		},
17|		engineState: { status: "idle", activeTaskId },
18|		listTasks: (projectId) => tasksByProject.get(projectId) ?? [],
19|		_recordHistory: vi.fn((task, action, timestamp) => {
20|			task.history = task.history || [];
21|			task.history.push({ timestamp, action });
22|		}),
23|		_saveTaskMarkdown: vi.fn(),
24|	};
25|	return store;
26|}
