28|function bootTask(overrides = {}) {
29|	return {
30|		id: "t-1",
31|		projectId: "p-1",
32|		status: "in_stage",
33|		updatedAt: "2026-09-24T10:00:00.000Z",
34|		history: [],
35|		...overrides,
36|	};
